import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"User-Facing Copy Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/index.md","filePath":"conventions/index.md"}'),n={name:"conventions/index.md"};function r(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="user-facing-copy-conventions" tabindex="-1">User-Facing Copy Conventions <a class="header-anchor" href="#user-facing-copy-conventions" aria-label="Permalink to &quot;User-Facing Copy Conventions&quot;">​</a></h1><p>Rules for any string a human eventually reads: emails, invoice line items and titles, manifest exports (XLSX / CSV), WhatsApp summaries, Telegram ops alerts, and API validation messages returned to a caller.</p><p>Internal strings — code comments, JSDoc, <code>Logger</code> output, and Swagger prose descriptions — are <strong>not</strong> covered here and may use whatever punctuation reads best.</p><hr><h2 id="rule-no-em-dash-—-u-2014-in-user-facing-strings" tabindex="-1">Rule: no em dash (<code>—</code>, U+2014) in user-facing strings <a class="header-anchor" href="#rule-no-em-dash-—-u-2014-in-user-facing-strings" aria-label="Permalink to &quot;Rule: no em dash (`—`, U+2014) in user-facing strings&quot;">​</a></h2><p>Use the ASCII hyphen <code>-</code> as a separator, or rephrase into separate sentences.</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>Failure mode with <code>—</code></th></tr></thead><tbody><tr><td>Email (HTML + text)</td><td>Clients that fall back to a legacy single-byte charset render a replacement glyph instead of the dash. Indonesian prose has no em-dash convention, so it reads as noise even when it renders.</td></tr><tr><td>XLSX / CSV export</td><td>The placeholder is outside the legacy code pages some spreadsheet clients fall back to, and nobody filtering a sheet types an em dash.</td></tr><tr><td>Telegram (MarkdownV2)</td><td>Not reserved, so it silently passes — but it is inconsistent with every other separator in the alert, which must use the escaped <code>\\-</code>.</td></tr><tr><td>Invoice line items / titles</td><td>Copied into accounting systems and searched by finance. <code>-</code> is typeable; <code>—</code> is not.</td></tr><tr><td>Validation messages</td><td>Echoed verbatim into client-side toasts and logs of unknown encoding.</td></tr></tbody></table><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><ul><li><strong>Separator between a label and a value</strong> → ASCII hyphen surrounded by spaces: <code>Custom booking - SUB → MED</code>.</li><li><strong>Parenthetical clause in prose</strong> → split into two sentences, or use a semicolon. Do not swap an em dash for a hyphen mid-sentence; it reads as a typo.</li><li><strong>Absent value in a tabular export</strong> → the shared placeholder constant, never a literal.</li></ul><blockquote><p>The <code>→</code> arrow (U+2192) inside route labels is deliberate and stays. It is a value, not punctuation, and every surface that renders it is UTF-8.</p></blockquote><hr><h2 id="shared-placeholder-for-absent-values" tabindex="-1">Shared placeholder for absent values <a class="header-anchor" href="#shared-placeholder-for-absent-values" aria-label="Permalink to &quot;Shared placeholder for absent values&quot;">​</a></h2><p>The manifest surfaces — the XLSX export, the CSV export, and the WhatsApp booking summary — render a missing value through one exported constant:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// src/modules/custom-booking/utils/booking-summary-shared.util.ts</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> EMPTY_VALUE_PLACEHOLDER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;-&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Import it — do not re-type the literal. It backs <code>formatPureDate</code>, <code>resolveSex</code>, and <code>formatNationalityName</code> (which the XLSX <strong>and</strong> CSV exports both consume), plus the airline / PNR / ID-number cells in the XLSX export and the return-date line of the WhatsApp booking summary, so every empty cell across all three surfaces stays identical.</p><hr><h2 id="rendered-strings-for-reference" tabindex="-1">Rendered strings, for reference <a class="header-anchor" href="#rendered-strings-for-reference" aria-label="Permalink to &quot;Rendered strings, for reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Format</th></tr></thead><tbody><tr><td>Invoice line item (per-pax)</td><td><code>{Pax type} - {origin} to {destination}</code> — e.g. <code>Adult - Surabaya to Madinah</code></td></tr><tr><td>Invoice line item (fallback lump)</td><td><code>Ticket - {origin} to {destination}</code></td></tr><tr><td>Invoice purpose, custom booking</td><td><code>Custom booking - {origin} → {destination}</code></td></tr><tr><td>Invoice purpose, OTA booking</td><td><code>Flight booking - {origin} → {destination}</code> (<code>BlockSeat booking - …</code> for the BlockSeat variant)</td></tr><tr><td>Invoice purpose, mitra registration</td><td><code>{TIER} partner {deposit|registration} - {registrationNumber}</code></td></tr><tr><td>Telegram terminal-failure alert</td><td><code>🚨 *Terminal OTA error \\- booking auto\\-FAILED*</code></td></tr><tr><td>Manifest empty cell</td><td><code>-</code></td></tr></tbody></table><blockquote><p><strong>Persisted vs derived.</strong> Changing a rendered format only takes effect retroactively where the string is derived on read. <code>purpose.title</code> is rebuilt per request, so it normalizes everywhere at once. <code>lineItems[].description</code> is written into a <code>Json</code> column at invoice generation and is <strong>not</strong> backfilled, so historical rows keep whatever separator shipped at the time. When you change a persisted string, say so in the Swagger description and the guide — and never let a consumer parse it.</p></blockquote><p>See <a href="/ahlaan-train-docs/admin/invoice/">Admin Invoice</a> for the full invoice payload shape.</p><hr><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>There is no lint rule. The guard is test coverage on the surfaces that matter:</p><ul><li><code>src/modules/email/templates/otp-email.template.spec.ts</code> asserts no OTP email body contains <code>—</code>.</li><li><code>src/modules/custom-booking/utils/booking-summary-shared.util.spec.ts</code> pins <code>EMPTY_VALUE_PLACEHOLDER</code> to the ASCII hyphen.</li><li><code>src/modules/telegram-bot/telegram-bot.service.spec.ts</code> pins the alert heading, including its MarkdownV2 escaping.</li></ul><p>When you add a new user-facing surface, add the equivalent assertion.</p>',26)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
